) AS t
LEFT JOIN region r ON r.province = t.province AND r.city = t.city AND r.area = t.area AND r.status = 1
WHERE NOT EXISTS (SELECT 1 FROM address a WHERE a.name = t.name AND a.longitude = t.longitude AND a.latitude = t.latitude AND a.status = 1);

INSERT INTO address (name, description, region_id, longitude, latitude, img_obj_name, status)
SELECT t.name, t.description, IFNULL(r.id, 0), t.longitude, t.latitude, t.img_obj_name, t.status
FROM (
SELECT '肯德基' AS name, '山东省 青岛市' AS description, '山东省' AS province, '青岛市' AS city, '' AS area, 120.31858931364499 AS longitude, 36.06760426245346 AS latitude, 'address/brand/kfc.png' AS img_obj_name, 1 AS status
