) AS t
LEFT JOIN region r ON r.province = t.province AND r.city = t.city AND r.area = t.area AND r.status = 1
WHERE NOT EXISTS (SELECT 1 FROM address a WHERE a.name = t.name AND a.longitude = t.longitude AND a.latitude = t.latitude AND a.status = 1);

INSERT INTO address (name, description, region_id, longitude, latitude, img_obj_name, status)
SELECT t.name, t.description, IFNULL(r.id, 0), t.longitude, t.latitude, t.img_obj_name, t.status
FROM (
SELECT '肯德基' AS name, '江苏省 常州市' AS description, '江苏省' AS province, '常州市' AS city, '' AS area, 120.13027362515928 AS longitude, 31.829836080562995 AS latitude, 'address/brand/kfc.png' AS img_obj_name, 1 AS status
UNION ALL
SELECT '肯德基' AS name, '重庆市 重庆市' AS description, '重庆市' AS province, '重庆市' AS city, '' AS area, 106.59355199629354 AS longitude, 29.551687682794043 AS latitude, 'address/brand/kfc.png' AS img_obj_name, 1 AS status
) AS t
LEFT JOIN region r ON r.province = t.province AND r.city = t.city AND r.area = t.area AND r.status = 1
WHERE NOT EXISTS (SELECT 1 FROM address a WHERE a.name = t.name AND a.longitude = t.longitude AND a.latitude = t.latitude AND a.status = 1);

